import{_ as e}from"./chunks/nada-installer.bJ5f3Qf1.js";import{_ as i,o as t,c as s,ag as n}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"Installation (Windows server)","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/platform-windows.md","filePath":"installation-guide/platform-windows.md","lastUpdated":1786379412000}'),o={name:"installation-guide/platform-windows.md"};function r(l,a,d,h,p,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="installation-windows-server" tabindex="-1">Installation (Windows server) <a class="header-anchor" href="#installation-windows-server" aria-label="Permalink to &quot;Installation (Windows server)&quot;">​</a></h1><p>How to install NADA on <strong>Windows Server with IIS</strong>, PHP, and either <strong>MySQL 8.x / MariaDB 10.x+</strong> or <strong>Microsoft SQL Server</strong>.</p><p>Before you start: <a href="./">Installation overview</a> (requirements and folder layout).<br> Pattern aligned with the Metadata Editor <a href="https://worldbank.github.io/metadata-editor-docs/tech_installation_windows.html" target="_blank" rel="noreferrer">Windows installation</a>.</p><p>IIS on Windows 10/11 Pro — the same steps apply; enable IIS and CGI via “Turn Windows features on or off.”</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Version</th></tr></thead><tbody><tr><td>OS</td><td>Windows Server with <strong>IIS 10+</strong> recommended</td></tr><tr><td>PHP</td><td><strong>7.4</strong> minimum; <strong>8.x recommended</strong> — <strong>Non-Thread Safe (NTS) x64</strong> for IIS</td></tr><tr><td>Database</td><td><strong>MySQL 8.x</strong> / <strong>MariaDB 10.x+</strong>, <em>or</em> <strong>SQL Server</strong> 2012+ with full-text</td></tr><tr><td>Web server</td><td>IIS 10+ with CGI / FastCGI</td></tr><tr><td>PHP Manager for IIS</td><td><strong>Optional but recommended</strong></td></tr><tr><td>URL Rewrite</td><td>Optional — <a href="https://www.iis.net/downloads/microsoft/url-rewrite" target="_blank" rel="noreferrer">iis.net URL Rewrite</a></td></tr></tbody></table><p>Enable <strong>IIS</strong> and the <strong>CGI</strong> feature (Server Manager or Windows Features) before registering PHP.</p><hr><h2 id="step-1-install-php-and-register-it-with-iis" tabindex="-1">Step 1: Install PHP and register it with IIS <a class="header-anchor" href="#step-1-install-php-and-register-it-with-iis" aria-label="Permalink to &quot;Step 1: Install PHP and register it with IIS&quot;">​</a></h2><h3 id="_1a-download-php" tabindex="-1">1a. Download PHP <a class="header-anchor" href="#_1a-download-php" aria-label="Permalink to &quot;1a. Download PHP&quot;">​</a></h3><ol><li>Download <strong>PHP NTS x64</strong> from <a href="https://windows.php.net/download/" target="_blank" rel="noreferrer">windows.php.net</a> (prefer <strong>8.x</strong>; minimum <strong>7.4</strong>).</li><li>Extract to a stable path, for example <code>C:\\PHP</code> or <code>C:\\PHP\\8.3</code>.</li><li>Copy <code>php.ini-production</code> to <code>php.ini</code> if needed.</li></ol><h3 id="_1b-php-manager-for-iis-recommended" tabindex="-1">1b. PHP Manager for IIS (recommended) <a class="header-anchor" href="#_1b-php-manager-for-iis-recommended" aria-label="Permalink to &quot;1b. PHP Manager for IIS (recommended)&quot;">​</a></h3><p><a href="https://www.iis.net/downloads/community/2018/05/php-manager-150-for-iis-10" target="_blank" rel="noreferrer">PHP Manager for IIS</a> registers PHP and manages extensions from IIS Manager.</p><ol><li>Install PHP Manager (match your IIS version); restart IIS Manager.</li><li>IIS Manager → server node → <strong>PHP Manager</strong> → <strong>Register new PHP version</strong> → select <code>php-cgi.exe</code> (e.g. <code>C:\\PHP\\php-cgi.exe</code>).</li><li>Enable extensions: <ul><li><code>xsl</code> / <code>php_xsl.dll</code></li><li><code>mbstring</code></li><li><code>mysqli</code> — MySQL or MariaDB</li><li><code>sqlsrv</code> — only if using SQL Server (install drivers first: <a href="./installation-sqlsrv.html">SQL Server guide</a>)</li></ul></li><li>Use <strong>Check phpinfo()</strong> (or a temporary <code>info.php</code>), confirm extensions, then <strong>delete</strong> any test <code>info.php</code>.</li></ol><p>Recycle the app pool (or use PHP Manager refresh) after <code>php.ini</code> changes.</p><h3 id="_1c-manual-fastcgi-without-php-manager" tabindex="-1">1c. Manual FastCGI (without PHP Manager) <a class="header-anchor" href="#_1c-manual-fastcgi-without-php-manager" aria-label="Permalink to &quot;1c. Manual FastCGI (without PHP Manager)&quot;">​</a></h3><ol><li>Confirm CGI/FastCGI is installed for IIS.</li><li>IIS Manager → <strong>Handler Mappings</strong> → <strong>Add Module Mapping</strong>: <ul><li>Request path: <code>*.php</code></li><li>Module: <code>FastCgiModule</code></li><li>Executable: <code>C:\\PHP\\php-cgi.exe</code></li><li>Name: e.g. <code>PHP_via_FastCGI</code></li></ul></li><li>Edit <code>php.ini</code> — see <a href="./php-settings.html">PHP settings</a>.</li><li>Recycle the application pool.</li></ol><h3 id="_1d-recommended-php-ini-values" tabindex="-1">1d. Recommended php.ini values <a class="header-anchor" href="#_1d-recommended-php-ini-values" aria-label="Permalink to &quot;1d. Recommended php.ini values&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 256M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_execution_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 300</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">post_max_size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 800M</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">upload_max_filesize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 800M</span></span></code></pre></div><p>More: <a href="./php-settings.html">PHP settings</a>.</p><hr><h2 id="step-2-folder-layout-and-download" tabindex="-1">Step 2: Folder layout and download <a class="header-anchor" href="#step-2-folder-layout-and-download" aria-label="Permalink to &quot;Step 2: Folder layout and download&quot;">​</a></h2><p>Typical path:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\inetpub\\wwwroot\\nada</span></span></code></pre></div><p>Create the folder. The application root must contain <code>index.php</code> (see <a href="./#standard-folder-layout">folder layout</a>).</p><p><strong>Download options:</strong></p><ol><li><strong>Zip (recommended for production):</strong> <a href="https://github.com/ihsn/nada/releases" target="_blank" rel="noreferrer">NADA Releases</a> — extract so <code>index.php</code> is under <code>C:\\inetpub\\wwwroot\\nada</code> (remove an extra nested folder if the zip creates one).</li><li><strong>Git:</strong> <a href="./installation-git.html">Install with Git</a>, then continue from Step 3.</li></ol><p>Prefer tagged releases for production.</p><hr><h2 id="step-3-database" tabindex="-1">Step 3: Database <a class="header-anchor" href="#step-3-database" aria-label="Permalink to &quot;Step 3: Database&quot;">​</a></h2><p>Choose <strong>one</strong> database for the whole install.</p><h3 id="option-a-—-mysql-8-x-or-mariadb-10-x" tabindex="-1">Option A — MySQL 8.x or MariaDB 10.x+ <a class="header-anchor" href="#option-a-—-mysql-8-x-or-mariadb-10-x" aria-label="Permalink to &quot;Option A — MySQL 8.x or MariaDB 10.x+&quot;">​</a></h3><ol><li>Install <a href="https://dev.mysql.com/downloads/mysql/" target="_blank" rel="noreferrer">MySQL</a> or MariaDB for Windows; set and record the root password.</li><li>Create database and user (Workbench, MariaDB client, or CLI):</li></ol><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DATABASE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> nada</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> CHARACTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> utf8mb4 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COLLATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> utf8mb4_unicode_ci;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nada</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&#39;@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IDENTIFIED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;yourpassword&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INSERT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INDEX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TEMPORARY TABLES, LOCK TABLES </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> nada.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;nada&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FLUSH PRIVILEGES;</span></span></code></pre></div><ol start="3"><li>In the NADA folder, copy <code>application\\config\\database-sample.php</code> to <code>database.php</code> and set credentials with <code>dbdriver</code> = <code>mysqli</code>.</li></ol><p>Full field reference and sample array: <a href="./database-mysql.html">Configure MySQL / MariaDB</a>.</p><h3 id="option-b-—-microsoft-sql-server" tabindex="-1">Option B — Microsoft SQL Server <a class="header-anchor" href="#option-b-—-microsoft-sql-server" aria-label="Permalink to &quot;Option B — Microsoft SQL Server&quot;">​</a></h3><p>SQL Server is a <strong>full install option</strong>, not an add-on.</p><ol><li>Ensure SQL Server has <strong>full-text</strong> enabled.</li><li>Install PHP <strong>sqlsrv</strong> drivers and (if needed) SQL Client — follow <strong><a href="./installation-sqlsrv.html">Install with SQL Server</a></strong> through <code>database.php</code> configuration.</li><li>Enable the <code>sqlsrv</code> extension in PHP Manager (or <code>php.ini</code>), then return here for Step 4.</li></ol><hr><h2 id="step-4-permissions" tabindex="-1">Step 4: Permissions <a class="header-anchor" href="#step-4-permissions" aria-label="Permalink to &quot;Step 4: Permissions&quot;">​</a></h2><p>Grant the IIS application pool identity <strong>Modify</strong> on <code>datafiles</code>, <code>logs</code>, and <code>files</code> (create the folders if missing).</p><p>Default identity:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IIS AppPool\\DefaultAppPool</span></span></code></pre></div><p>Elevated command prompt (from the NADA root):</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">icacls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> datafiles /grant </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;IIS AppPool\\DefaultAppPool:(OI)(CI)M&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /T</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">icacls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> logs /grant </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;IIS AppPool\\DefaultAppPool:(OI)(CI)M&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /T</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">icacls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> files /grant </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;IIS AppPool\\DefaultAppPool:(OI)(CI)M&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /T</span></span></code></pre></div><p>For a custom app pool, use <code>IIS AppPool\\&lt;YourAppPoolName&gt;</code>.</p><div class="tip custom-block"><p class="custom-block-title">Security</p><p>Consider locating <code>datafiles</code> outside <code>inetpub</code> after install.</p></div><hr><h2 id="step-5-configure-the-iis-site" tabindex="-1">Step 5: Configure the IIS site <a class="header-anchor" href="#step-5-configure-the-iis-site" aria-label="Permalink to &quot;Step 5: Configure the IIS site&quot;">​</a></h2><ol><li>Open <strong>IIS Manager</strong>.</li><li>Add a <strong>Website</strong> or <strong>Application</strong> with physical path = NADA application root (<code>...\\nada</code> where <code>index.php</code> lives).</li><li>Application pool: <strong>No Managed Code</strong>, <strong>Integrated</strong> pipeline.</li><li>Confirm <code>.php</code> maps to FastCGI (PHP Manager or Step 1c).</li><li>Recycle the app pool after PHP changes.</li></ol><p>Optional: install <a href="https://www.iis.net/downloads/microsoft/url-rewrite" target="_blank" rel="noreferrer">URL Rewrite</a>. Apache-oriented clean URL docs: <a href="./configurations/clean-urls.html">Clean URLs</a>.</p><hr><h2 id="step-6-run-the-web-installer" tabindex="-1">Step 6: Run the web installer <a class="header-anchor" href="#step-6-run-the-web-installer" aria-label="Permalink to &quot;Step 6: Run the web installer&quot;">​</a></h2><ol><li>Browse to <code>http://localhost/nada</code> (or your site binding/host header).</li><li>Fix any failed prerequisite checks (extensions, writable folders, database).</li><li>Click <strong>Install Database</strong> and create the Site Administrator account.</li></ol><p><img src="`+e+'" alt="NADA installer"></p><div class="tip custom-block"><p class="custom-block-title">Complex password</p><p>Use at least 12 characters with uppercase, numbers, and punctuation. Do not lose this account.</p></div><hr><h2 id="step-7-post-install" tabindex="-1">Step 7: Post-install <a class="header-anchor" href="#step-7-post-install" aria-label="Permalink to &quot;Step 7: Post-install&quot;">​</a></h2><ol><li><a href="./configurations/email.html">Email</a> and other <a href="./configurations/">Configurations</a></li><li>Optional: <a href="./installation-solr.html">Solr</a>, themes, CSP</li><li><a href="/nada-documentation/getting-started/">Getting started</a></li></ol><h3 id="hardening" tabindex="-1">Hardening <a class="header-anchor" href="#hardening" aria-label="Permalink to &quot;Hardening&quot;">​</a></h3><ul><li>Dedicated DB user (not <code>root</code> / <code>sa</code>)</li><li>Strong admin password</li><li>Delete temporary <code>info.php</code></li><li>Move <code>datafiles</code> outside the web root when possible</li><li>Plan backups (<a href="/nada-documentation/admin-guide/web-ui/backup.html">Backup</a>)</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>What to check</th></tr></thead><tbody><tr><td>500 / handler errors</td><td>PHP Manager registration or FastCGI mapping; path to <code>php-cgi.exe</code>; recycle app pool</td></tr><tr><td>Wrong php.ini / missing extensions</td><td>PHP Manager phpinfo; enable extensions; <a href="./php-settings.html">PHP settings</a></td></tr><tr><td>Installer cannot write</td><td>App pool identity on <code>datafiles</code>, <code>files</code>, <code>logs</code></td></tr><tr><td>Database connection failed</td><td><code>database.php</code>; MySQL service or SQL Server / sqlsrv drivers</td></tr><tr><td>PHP Manager missing</td><td>Correct IIS version installer; restart IIS Manager as administrator</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Installation overview</a> · <a href="./platform-linux.html">Installation (Linux)</a></li><li><a href="./database-mysql.html">Configure MySQL / MariaDB</a> · <a href="./installation-sqlsrv.html">Install with SQL Server</a></li><li><a href="./php-settings.html">PHP settings</a> · <a href="./configurations/">Configurations</a></li></ul>',69)])])}const m=i(o,[["render",r]]);export{u as __pageData,m as default};
